const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-0.819876, 53.083908]).buffer(5000);
  const date2024 = '2024-01-04';
  const date2022 = '2022-01-05';

  // Function to acquire and process Sentinel-1 data for water detection
  const getWaterExtent = (date, geometry) => {
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    // Use Sentinel-1 SAR as it's cloud-penetrating, reliable for water detection
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    // Check if any images are found
    if (collection.size().getInfo() === 0) {
      return { 'image_count': 0, 'water_pixels': null };
    }

    // Mosaic and clip the image for the specified day
    const image = collection.mosaic().clip(geometry);

    // Water is characterized by low backscatter in SAR imagery. A threshold is used to classify water.
    // A threshold of -16 dB is common for water bodies in VV polarization.
    const waterThreshold = -16;
    const waterMask = image.select('VV').lt(waterThreshold);

    // Calculate the number of water pixels
    const stats = waterMask.selfMask().reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 30, // Use a reasonable scale to avoid timeouts
      maxPixels: 1e9
    });

    return {
      'image_count': collection.size().getInfo(),
      'water_pixels': stats.get('VV')
    };
  };

  // 2. Data Acquisition & Processing
  const result2024 = getWaterExtent(date2024, aoi);
  const result2022 = getWaterExtent(date2022, aoi);

  // 3. Validation & Final Answer
  const images2024 = result2024['image_count'];
  const images2022 = result2022['image_count'];
  console.log(`Images found for 2024-01-04: ${images2024}`);
  console.log(`Images found for 2022-01-05: ${images2022}`);

  if (images2024 === 0 || images2022 === 0) {
    console.log("Evidence: No Sentinel-1 images were available for one or both of the specified dates.");
    console.log("A"); // C1
    return;
  }

  const waterPixels2024 = ee.Number(result2024['water_pixels']).getInfo();
  const waterPixels2022 = ee.Number(result2022['water_pixels']).getInfo();

  console.log(`2024 Water Pixel Count: ${waterPixels2024}`);
  console.log(`2022 Water Pixel Count: ${waterPixels2022}`);

  if (waterPixels2024 === null || waterPixels2022 === null) {
      console.log("Evidence: Calculation failed, returned a null value for pixel count.");
      console.log("C3");
      return;
  }

  if (waterPixels2024 === 0 && waterPixels2022 === 0) {
      console.log("Evidence: No water pixels detected on either date after processing.");
      console.log("C2");
      return;
  }

  if (waterPixels2024 > waterPixels2022) {
    console.log("Evidence: The water pixel count in 2024 was greater than in 2022.");
    console.log("A");
  } else {
    console.log("Evidence: The water pixel count in 2024 was not greater than in 2022.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
